@startuml

class TileO {}

class Game {
  + currentConnectionPieces : int
  + spareConnectionPieces : int = 32
}

class Connection {}

class Die {}

class Deck {}

abstract class Tile {
  + isVisited : boolean
}

abstract class ActionCard {
  + instructions : string
}

class ConnectTilesActionCard extends ActionCard {}

class RemoveConnectionActionCard extends ActionCard {}

class LoseTurnActionCard extends ActionCard {}

class WinTile extends Tile {}

class ActionTile extends Tile {
  + inactivityPeriod : int
  + turnsUntilActive : int
}

class NormalTile extends Tile {}

class PlayingPiece {
  + color : string
}

class Player {
  + position : int
}

TileO "1" *-- "*" Game
Game "1" *-- "*" Tile
Game "1" *-- "*" Connection
Game "1" *-- "1" Die
Game "1" *-- "1" Deck
Deck "1" *-- "32" ActionCard
Game "1" --> "0..1" WinTile
Tile "1" -- "0..4" Connection
Tile "1" -- "0..1" Connection : right
Tile "1" -- "0..1" Connection : left
Tile "1" -- "0..1" Connection : top
Tile "1" -- "0..1" Connection : bottom
Game "1" *-- "2..4" Player
Player "1" *-- "1" PlayingPiece
Game "1" --> "0..1" ActionTile
Game "1" --> "0..1" NormalTile

@enduml

